INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (29943, 'AT-3', 'A forensic program established to ensure that evidence is collected/handled in accordance with pertinent laws in case of an incident requiring civil or criminal action.', 'A SCADA tech believes a machine is infected. Based on their training, they remove the machine from the network and report it to IT without powering it off to avoid deleting evidence.', 'Governance and Risk Management', 'Governance and Risk Management', 0, NULL, 'AWWA', NULL, NULL, NULL, 88, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (29944, 'DS-1', 'A program established to ensure compliance with the minimum PCI requirements for your associated level.', 'The company selected to perform billing is compliant with the minimum PCI requirements for the utility''s associated level.', 'Data Security', 'Data Security', 0, NULL, 'AWWA', NULL, NULL, NULL, 86, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (29945, 'DS-3', 'A program is established to ensure compliance with the minimum HIPAA requirements. Develop a Privacy Policy as well as a Cyber Security Breach Policy.', 'Current practices are reviewed by legal counsel for legal compliance with HIPAA.', 'Data Security', 'Data Security', 0, NULL, 'AWWA', NULL, NULL, NULL, 86, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (29946, 'IA-1', 'Access control policies and procedures established including unique user ID for every user, appropriate passwords, privilege accounts, authentication, and management oversight.', 'Based on their knowledge of access control policies, operators do not share passwords.', 'Access Control', 'Access Control', 0, NULL, 'AWWA', NULL, NULL, NULL, 4, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (29947, 'IA-10', 'Policies and procedures for least privilege established to ensure that users only gain access to the authorized services.', 'If no user is logged in at a SCADA screen, a read-only view is presented. Individual roles created and assigned to users depending on their responsibilities.', 'Governance and Risk Management', 'Governance and Risk Management', 0, NULL, 'AWWA', NULL, NULL, NULL, 88, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (29948, 'IA-12', 'Session controls established to inactivate idle sessions, provide web content filtering, prevent access to malware sites, etc.', 'An operator attempts to connect to a known hacking website. The connection is blocked. The operator and IT are notified of the attempt.', 'Access Control', 'Access Control', 0, NULL, 'AWWA', NULL, NULL, NULL, 4, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (29949, 'IA-3', 'Role based access control system established including policies and procedures.', 'SCADA software implements unique usernames and passwords with different levels of control based on roles.', 'Access Control', 'Access Control', 0, NULL, 'AWWA', NULL, NULL, NULL, 4, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (29950, 'IA-4', 'Access control for confidential system documentation established to prevent unauthorized access of trade secrets, program source code, documentation, and passwords (including approved policies and procedures).', 'Defined clearance requirements for individuals to access confidential information.', 'Access Control', 'Access Control', 0, NULL, 'AWWA', NULL, NULL, NULL, 4, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (29951, 'IA-5', 'Access control for diagnostic tools and resources and configuration ports.', 'PLC programming software is only available at select workstations and only accessible to SCADA technicians.', 'Access Control', 'Access Control', 0, NULL, 'AWWA', NULL, NULL, NULL, 4, NULL)
