INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (29953, 'IA-7', 'Wireless and guest-access framework established for the management, monitoring, review, and audit of wireless and guest access in place.', 'To use the plant guest network, users are required to accept a user agreement.', 'Access Control', 'Access Control', 0, NULL, 'AWWA', NULL, NULL, NULL, 4, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (29954, 'PE-1', 'Security perimeters, card controlled gates, manned booths, and procedures for entry control.', 'Personnel are required to present a badge to access the PCS.', 'Physical Security', 'Physical Security', 0, NULL, 'AWWA', NULL, NULL, NULL, 33, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (29955, 'PE-2', 'Secure areas protected by entry controls and procedures to ensure that only authorized personnel have access.', 'Access to the server room is restricted to authorized staff only.', 'Access Control', 'Access Control', 0, NULL, 'AWWA', NULL, NULL, NULL, 4, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (29956, 'PE-3', 'Physical security and procedures for offices, rooms, and facilities.', 'Staff lock doors that allow access to PCS assets. Security guards inspect doors to make sure they are locked properly.', 'Access Control', 'Access Control', 0, NULL, 'AWWA', NULL, NULL, NULL, 4, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (29957, 'PE-4', 'Physical protection against fire, flood, earthquake, explosion, civil unrest, etc.', 'Fire suppression unit installed around critical equipment.', 'Governance and Risk Management', 'Governance and Risk Management', 0, NULL, 'AWWA', NULL, NULL, NULL, 88, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (29958, 'PE-5', 'Physical security and procedures for working in secure areas.', 'Documentation for physical security procedures is included with new employee training and reviewed at regular training events.', 'Access Control', 'Access Control', 0, NULL, 'AWWA', NULL, NULL, NULL, 4, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (29959, 'PE-6', 'Physical security and procedures for mail rooms, loading areas, etc., established.  These areas must be isolated from IT/PCS areas.', 'Server room and PLC cabinets are isolated from areas that delivery personnel and customers may visit.', 'Access Control', 'Access Control', 0, NULL, 'AWWA', NULL, NULL, NULL, 4, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (29960, 'PE-7', 'Physical security and procedures against equipment environmental threats and hazards or unauthorized access.', 'The utility monitors facilities using security cameras.', 'Physical Security', 'Physical Security', 0, NULL, 'AWWA', NULL, NULL, NULL, 33, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (29961, 'PE-8', 'Physical/logical protection against power failure of equipment (UPS).', 'Uninterruptible power supplies (UPS) are available as power backup for critical components.', 'Access Control', 'Access Control', 0, NULL, 'AWWA', NULL, NULL, NULL, 4, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (29962, 'PE-9', 'Physical/logical protection against access to power and telecommunications cabling established.', 'A utility has a standby power source with separated power cabling for critical sites.', 'Access Control', 'Access Control', 0, NULL, 'AWWA', NULL, NULL, NULL, 4, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (29963, 'SC-1', 'Policies and procedures governing cryptography and cryptographic protocols including key/certificate-management established to maximize protection of systems and information.', 'When selecting new PLCs for a system upgrade, SCADA techs evaluate the option of using newer PLCs that offer encryption for communication.', 'Governance and Risk Management', 'Governance and Risk Management', 0, NULL, 'AWWA', NULL, NULL, NULL, 88, NULL)
