INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (29967, 'SC-15', 'Logically separated control network. Minimal or single access points between corporate and control network. Stateful firewall between corporate and control networks filtering on TCP and UDP ports. DMZ networks for data sharing.', 'An actively managed firewall is in place to allow secure data transfer via DMZ to provide operations data to utility asset managers.', 'Telecommunications, Network Security, and Architecture', 'Telecommunications, Network Security, and Architecture', 0, NULL, 'AWWA', NULL, NULL, NULL, 72, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (29968, 'SC-16', 'Defense-in-depth. Multiple layers of security with overlapping functionality.', 'A utility employs multiple types of physical and cybersecurity efforts to protect assets and systems. The efforts include such things as locking doors, physical access control, and unique login requirements for each staff member.', 'Telecommunications, Network Security, and Architecture', 'Telecommunications, Network Security, and Architecture', 0, NULL, 'AWWA', NULL, NULL, NULL, 72, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (29969, 'SC-17', 'Virtual Local Area Network (VLAN) for logical network segregation.', 'Within the SCADA system network, vendor systems are on a separate subnet.', 'Telecommunications, Network Security, and Architecture', 'Telecommunications, Network Security, and Architecture', 0, NULL, 'AWWA', NULL, NULL, NULL, 72, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (29970, 'SC-18', 'Minimize wireless network coverage.', 'Tests are conducted regularly to determine if the WiFi signals reach outside the intended area of use. If the signal reaches outside the intended area, the signal is turned down accordingly.', 'Telecommunications, Network Security, and Architecture', 'Telecommunications, Network Security, and Architecture', 0, NULL, 'AWWA', NULL, NULL, NULL, 72, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (29971, 'SC-19', '802.1X user authentication on wireless networks.', 'No "open" WiFi connections are allowed.', 'Telecommunications, Network Security, and Architecture', 'Telecommunications, Network Security, and Architecture', 0, NULL, 'AWWA', NULL, NULL, NULL, 72, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (29972, 'SC-2', 'Centralized authentication system or single sign-on established to authorize access from a central system.', 'Operators have one username and password for PCS equipment which is managed from a central system.', 'Access Control', 'Access Control', 0, NULL, 'AWWA', NULL, NULL, NULL, 4, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (29973, 'SC-20', 'Wireless equipment located on isolated network with minimal or single connection to control network.', 'WiFi equipment in the plant does not connect directly to SCADA network.', 'Telecommunications, Network Security, and Architecture', 'Telecommunications, Network Security, and Architecture', 0, NULL, 'AWWA', NULL, NULL, NULL, 72, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (29974, 'SC-21', 'Unique wireless network indentifier (SSID) for control network.', 'The WiFi for the control system has a unique SSID from the business network.', 'Telecommunications, Network Security, and Architecture', 'Telecommunications, Network Security, and Architecture', 0, NULL, 'AWWA', NULL, NULL, NULL, 72, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (29975, 'SC-22', 'Separate Microsoft Windows domain for wireless (if using Windows).', 'A wireless LAN specific domain controller is in place.', 'Telecommunications, Network Security, and Architecture', 'Telecommunications, Network Security, and Architecture', 0, NULL, 'AWWA', NULL, NULL, NULL, 72, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (29976, 'SC-23', 'Wireless communications links encrypted.', 'All data transferred via the wireless network is encrypted using current wireless communication best practices.', 'Encryption', 'Encryption', 0, NULL, 'AWWA', NULL, NULL, NULL, 13, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (29977, 'SC-24', 'Communications links encrypted.', 'All data transferred via the wired network is encrypted using current wired communication best practices.', 'Encryption', 'Encryption', 0, NULL, 'AWWA', NULL, NULL, NULL, 13, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (29978, 'SC-25', 'Virtual Private Network (VPN) using IPsec, SSL or SSH to encrypt communications from untrusted networks to the control system network.', 'An operator who can access the system remotely must do so through a secured VPN client configuration.', 'Encryption', 'Encryption', 0, NULL, 'AWWA', NULL, NULL, NULL, 13, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (29979, 'SC-3', 'Policies and procedures established for network segmentation including implementation of DMZs based on type and sensitivity of equipment, user roles, and types of systems established.', 'All external communication with the PCS is implemented via DMZ.', 'Governance and Risk Management', 'Governance and Risk Management', 0, NULL, 'AWWA', NULL, NULL, NULL, 88, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (29980, 'SI-1', 'Electronic commerce infrastructure in place providing integrity, confidentiality and non-repudiation and including adherence to pertinent laws, regulations, policies, procedures, and approval by management.', 'The company selected to perform billing is compliant with pertinent laws, regulations, policies, procedures that are relevant to the utility.', 'Governance and Risk Management', 'Governance and Risk Management', 0, NULL, 'AWWA', NULL, NULL, NULL, 88, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (29981, 'SI-3', 'Interactive system for managing password implemented to ensure password strength.', 'When configuring a new user’s password, it must meet minimum character length requirements.', 'Access Control', 'Access Control', 0, NULL, 'AWWA', NULL, NULL, NULL, 4, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (29982, 'AT-1', 'A general security awareness and response program established to ensure staff is aware of the indications of a potential incident, security policies, and incident response/notification procedures.', 'An operator finds a USB media device. Based on their cybersecurity training, they know not to use it on the company network.', 'Education', 'Education', 0, NULL, 'AWWA', NULL, NULL, NULL, 87, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (29983, 'AU-1', 'Audit program established to ensure information systems are compliant with policies and standards and to minimize disruption of operations.', 'IT schedules an independent review and examination of records and activities to assess the adequacy of system controls and to ensure compliance with established policies.', 'Application Security', 'Application Security', 0, NULL, 'AWWA', NULL, NULL, NULL, 85, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (29984, 'AU-2', 'Framework of information security policies, procedures, and controls including management''s initial and periodic approval established to provide governance, exercise periodic review, dissemination, and coordination of information security activities.', 'The process of implementing policies and procedures is clearly defined and reviewed. Updates to this process are made by a responsible party.', 'Governance and Risk Management', 'Governance and Risk Management', 0, NULL, 'AWWA', NULL, NULL, NULL, 88, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (29985, 'AU-3', 'Governance framework to disseminate/decentralize decision making while maintaining executive authority and strategic control and ensure that managers follow the security policies and enforce the execution of security procedures within their area of respon', 'A utility has a required number of accountable staff that must review or provide input before security policies are put in place. Periodic review that approved security policies are being followed.', 'Governance and Risk Management', 'Governance and Risk Management', 0, NULL, 'AWWA', NULL, NULL, NULL, 88, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (29986, 'AU-4', 'Information security responsibilities defined and assigned.', 'All staff are aware of who they would report to if they notice suspicious behavior in the system.', 'Governance and Risk Management', 'Governance and Risk Management', 0, NULL, 'AWWA', NULL, NULL, NULL, 88, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (29987, 'AU-5', 'Risk based business continuity framework established under the auspices of the executive team to maintain continuity of operations and consistency of policies and plans throughout the organization.  Another purpose of the framework is to ensure consistenc', 'The facility has a documented and tested contingency plan to operate the facility without the use of SCADA software, in the case of attack by ransomware.', 'Business Continuity and Disaster Recovery', 'Business Continuity and Disaster Recovery', 0, NULL, 'AWWA', NULL, NULL, NULL, 81, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (29988, 'AU-6', 'Policies and procedures established to validate, test, update and audit the business continuity plan throughout the organization.', 'The business continuity plan is revised annually. Revisions are informed by planned exercises, actual events, or documented changes.', 'Governance and Risk Management', 'Governance and Risk Management', 0, NULL, 'AWWA', NULL, NULL, NULL, 88, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (29989, 'AU-7', 'Policies and procedures for system instantiation/deployment established to ensure business continuity.', 'The PCS has a testing/development environment to allow changes to be implemented without immediate effects to the production environment.', 'Business Continuity and Disaster Recovery', 'Business Continuity and Disaster Recovery', 0, NULL, 'AWWA', NULL, NULL, NULL, 81, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (29990, 'CM-3', 'Separation of duties implemented for user processes including risk of abuse.', 'Operators are only given clearance to areas they are expected to work in. Supervisors have the ability and training to monitor SCADA tech activities in the PCS.', 'Application Security', 'Application Security', 0, NULL, 'AWWA', NULL, NULL, NULL, 85, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (29991, 'CM-4', 'Separation of duties implemented for development, production, and testing work.', 'A SCADA technician must have a second technician review changes made to production equipment before they are implemented.', 'Application Security', 'Application Security', 0, NULL, 'AWWA', NULL, NULL, NULL, 85, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (29992, 'CM-5', 'SLAs for all third parties established, including levels of service and change controls.', 'A security policy that outlines what access permissions are distributed to third party employees.', 'Service Level Agreements (SLA)', 'Service Level Agreements (SLA)', 0, NULL, 'AWWA', NULL, NULL, NULL, 90, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (29993, 'CM-7', 'Monitoring of resources and capabilities with notifications and alarms established to alert management when resources/capabilities fall below a threshold.', 'IT monitors SCADA computers for processor usage that could indicate cryptojacking activity.', 'Service Level Agreements (SLA)', 'Service Level Agreements (SLA)', 0, NULL, 'AWWA', NULL, NULL, NULL, 90, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (29994, 'IA-11', 'Workstation and other equipment authentication framework established to secure sensitive access from certain high risk locations.', 'Access to control of critical equipment is only available at a secured terminal.', 'Access Control', 'Access Control', 0, NULL, 'AWWA', NULL, NULL, NULL, 4, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (29995, 'IA-9', 'Multifactor authentication system established for critical areas.', 'Remote access to the SCADA system requires two factor-authentication.', 'Access Control', 'Access Control', 0, NULL, 'AWWA', NULL, NULL, NULL, 4, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (29996, 'IR-1', 'Incident response program established with a formal Emergency Response Plan to restore systems and operations based on their criticality and within time constraints and effect recovery in case of a catalogue of disruptive events.  Exercises conducted to t', 'Emergency Response Plan includes procedures for recovering SCADA system operation from system backup.', 'Governance and Risk Management', 'Governance and Risk Management', 0, NULL, 'AWWA', NULL, NULL, NULL, 88, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (29997, 'PM-3', 'Centralized logging system including policies and procedures to collect, analyze and report to management.', 'A utility has a network intrusion detection system (NIDS) to monitor network traffic.', 'Telecommunications, Network Security, and Architecture', 'Telecommunications, Network Security, and Architecture', 0, NULL, 'AWWA', NULL, NULL, NULL, 72, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (29998, 'PM-4', 'SLAs for software and information exchange with internal/external parties in place including interfaces between systems and approved policies and procedures.', 'Third parties must review and sign an information exchange policy before connecting to the system.', 'Service Level Agreements (SLA)', 'Service Level Agreements (SLA)', 0, NULL, 'AWWA', NULL, NULL, NULL, 90, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (29999, 'RA-1', 'Risk assessment and approval process before granting access to the organization''s information systems.', 'A third-party system integrator would need to contact IT before connecting to the system’s network.', 'Governance and Risk Management', 'Governance and Risk Management', 0, NULL, 'AWWA', NULL, NULL, NULL, 88, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (30000, 'RA-2', 'Third party agreement process to ensure that external vendors and contractors utilize appropriate security measures for access, processing, communicating, or managing the organization''s information or facilities.', 'System integrators can only access the facility''s equipment remotely from a VPN connection.', 'Governance and Risk Management', 'Governance and Risk Management', 0, NULL, 'AWWA', NULL, NULL, NULL, 88, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (30001, 'SC-10', 'Program for hardening servers, workstations, routers, and other systems using levels of hardening based on criticality established. Program should include policies and procedures for whitelisting (deny-all, allow by exception).', 'Ports are disabled for all network devices when not in use.', 'Server and Workstation Hardening', 'Server and Workstation Hardening', 0, NULL, 'AWWA', NULL, NULL, NULL, 43, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (30002, 'SC-4', 'Intrusion detection, prevention, and recovery systems including approved policies and procedures established to protect against cyber-attacks. System includes repository of fault logging, analysis, and appropriate actions taken.', 'Monitoring of IDS is conducted to determine if ongoing attacks are occurring and incidence response actions have been documented.', 'Telecommunications, Network Security, and Architecture', 'Telecommunications, Network Security, and Architecture', 0, NULL, 'AWWA', NULL, NULL, NULL, 72, NULL)
