INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (30005, 'SC-7', 'Information exchange protection program in place to protect data in-transit through any communication system including the Internet, email, and text messaging and approved policies and procedures.', 'Web applications for SCADA software use encryption to protect data in transit.', 'Telecommunications, Network Security, and Architecture', 'Telecommunications, Network Security, and Architecture', 0, NULL, 'AWWA', NULL, NULL, NULL, 72, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (30006, 'SC-8', 'Routing controls established to provide logical separation of sensitive systems and enforce the organization''s access control policy.', 'Within the SCADA system network, vendor systems are placed on a separate subnet rather than being on a single "flat" network.', 'Telecommunications, Network Security, and Architecture', 'Telecommunications, Network Security, and Architecture', 0, NULL, 'AWWA', NULL, NULL, NULL, 72, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (30007, 'SC-9', 'Process isolation established to provide a manual override “air gap” between highly sensitive systems and regular environments.', 'A manual method for disconnecting the ICS network from other networks is implemented and documented.', 'Operations Security', 'Operations Security', 0, NULL, 'AWWA', NULL, NULL, NULL, 89, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (30008, 'SI-5', 'Privileged programs controls established to restrict usage of utility programs that could reset passwords or override controls as well as IT audit tools that can modify or delete audit data.', 'Utility has implemented tiered access so non-administrator users are unable to make changes to system security settings.', 'Application Security', 'Application Security', 0, NULL, 'AWWA', NULL, NULL, NULL, 85, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (30009, 'AT-2', 'Job specific security training including incident response training for employees, contractors and third party users.', 'An operator has received what they believe to be a malicious email. They recognize that it is a phishing attack based on security training awareness programs the company has in place.', 'Education', 'Education', 0, NULL, 'AWWA', NULL, NULL, NULL, 87, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (30010, 'AU-8', 'Template for the organization''s confidentiality/non-disclosure agreements defined, reviewed, and approved periodically by management.', 'Reviews of the organization’s confidentiality/non-disclosure agreements are periodically scheduled by a responsible party.', 'Governance and Risk Management', 'Governance and Risk Management', 0, NULL, 'AWWA', NULL, NULL, NULL, 88, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (30011, 'CIE-1', 'A program is in place to engage engineering staff in understanding and mitigating high-consequence and constantly evolving cyber threat throughout the engineering life-cycle including: design, implementation, maintenance, and decommissioning.', 'Engineering staff is fully aware of the potential for a cyber breach. They design electrical and mechanical systems to provide functionality in the case of a SCADA system compromise.', 'Cyber-Informed Engineering', 'Cyber-Informed Engineering', 0, NULL, 'AWWA', NULL, NULL, NULL, 50, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (30012, 'CM-1', 'Policies for defining business requirements including data validation and message authenticity established to ensure that new/upgraded systems contain appropriate security requirements and controls.', 'Policies to define minimum security features (i.e. secure protocols, active directory integration, etc.) required for new systems. This could include review and approval by change management and/or security team.', 'Governance and Risk Management', 'Governance and Risk Management', 0, NULL, 'AWWA', NULL, NULL, NULL, 88, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (30013, 'CM-2', 'Procedure modification tracking program in place to manage and log changes to policies and procedures.', 'The Emergency Response Plan is stored in a central repository and clearly displays the version and date of when it was implemented.', 'Governance and Risk Management', 'Governance and Risk Management', 0, NULL, 'AWWA', NULL, NULL, NULL, 88, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (30014, 'IA-8', 'Policies for security of standalone, lost, and misplaced equipment in place.', 'An operator misplaces a managed phone. Based on the missing equipment policy, they contact IT to report the device lost.', 'Governance and Risk Management', 'Governance and Risk Management', 0, NULL, 'AWWA', NULL, NULL, NULL, 88, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (30015, 'IR-3', 'A legal/contractual/regulatory framework established with a formal Emergency Response Plan to track legal/contractual/regulatory requirements and the efforts to meet them with respect to each important system within the organization. Another purpose of th', 'The Emergency Response Plan is reviewed and updated once a year by responsible staff.', 'Governance and Risk Management', 'Governance and Risk Management', 0, NULL, 'AWWA', NULL, NULL, NULL, 88, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (30016, 'MA-3', 'Off-site equipment maintenance program including risk assessment of outside environmental conditions established.', 'The condition of offsite equipment and risk factors acting on the equipment are periodically reviewed and assessed via an independent party.', 'Governance and Risk Management', 'Governance and Risk Management', 0, NULL, 'AWWA', NULL, NULL, NULL, 88, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (30017, 'MP-2', 'Information exit mechanisms in place to prevent data, software leaving premises without authorization or logging.', 'An approved data leakage prevention (DLP) system is implemented or manual procedures to control data and/or software leaving organization.', 'Governance and Risk Management', 'Governance and Risk Management', 0, NULL, 'AWWA', NULL, NULL, NULL, 88, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (30018, 'PM-1', 'An asset inventory of all electronic components including model, software / firmware, etc. that is maintained and referenced when vendor vulnerabilities are disclosed.', 'A database is used to keep track of building conditions in the facility.', 'Governance and Risk Management', 'Governance and Risk Management', 0, NULL, 'AWWA', NULL, NULL, NULL, 88, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (30019, 'PM-2', 'Policies and procedures for acceptable use of assets and information approved and implemented.', 'PLCs that cannot update past a specific security revision are not acceptable for use in the PCS.', 'Governance and Risk Management', 'Governance and Risk Management', 0, NULL, 'AWWA', NULL, NULL, NULL, 88, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (30020, 'PS-1', 'Policies and procedures for hiring/terminating processes on employees, contractors, or support companies to include background checks and contract agreements approved and implemented.', 'A background check on employees is required before they may be given access to the PCS system.', 'Personnel Security', 'Personnel Security', 0, NULL, 'AWWA', NULL, NULL, NULL, 67, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (30021, 'PS-2', 'Defined and approved security roles and responsibilities of all employees, contractors and third party users.', 'A company policy is in place limiting the access of third-party users to assets, systems, and data.', 'Personnel Security', 'Personnel Security', 0, NULL, 'AWWA', NULL, NULL, NULL, 67, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (30022, 'PS-3', 'A clear desk policy in place including clear papers, media, desktop, and computer screens.', 'Confidential documents are stored in locked file cabinets when not in use, as required by policy.', 'Personnel Security', 'Personnel Security', 0, NULL, 'AWWA', NULL, NULL, NULL, 67, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (30023, 'PS-4', 'Disciplinary process for security violations established.', 'An operator who props open doors to critical areas could face disciplinary action as outlined in the utility''s policies and procedures.', 'Personnel Security', 'Personnel Security', 0, NULL, 'AWWA', NULL, NULL, NULL, 67, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (30024, 'SA-1', 'Authorization process established for new systems or changes to existing information processing systems.', 'A change management/review process is used to evaluate suggested changes to facility.', 'Governance and Risk Management', 'Governance and Risk Management', 0, NULL, 'AWWA', NULL, NULL, NULL, 88, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (30025, 'SA-2', 'Change controls of systems development, outsourced development, system modification, and testing established, including acceptance criteria for new systems, monitoring of internal/outsourced development, and control of system upgrades.', 'A third-party system integrator is preparing to make changes to SCADA software. The SCADA tech requires the integrator to follow the change procedure and test the changes in a sandbox environment before they are deployed in production.', 'Governance and Risk Management', 'Governance and Risk Management', 0, NULL, 'AWWA', NULL, NULL, NULL, 88, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (30026, 'SA-3', 'Change controls of operating systems, network configuration/topology, network security established, including changes to IDS/IPS, traffic control/monitoring, new systems, and system upgrades.', 'Automatic updates to the operating system are disabled, but monthly manual updates are reviewed and applied in coordination with operations.', 'Governance and Risk Management', 'Governance and Risk Management', 0, NULL, 'AWWA', NULL, NULL, NULL, 88, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (30027, 'SA-4', 'Risk based mobility policies and procedures established to protect against inherent risk of mobile computing and communication systems.', 'Remote access is restricted to only the most necessary applications and only allowed through secure measures.', 'Operations Security', 'Operations Security', 0, NULL, 'AWWA', NULL, NULL, NULL, 89, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (30028, 'SA-5', 'Periodic review of backup policies and procedures and testing of recovery processes.', 'System backups are tested on a regular basis by completing a system restoration to the test environment.', 'Governance and Risk Management', 'Governance and Risk Management', 0, NULL, 'AWWA', NULL, NULL, NULL, 88, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (30029, 'SC-13', 'Testing standards including test data selection, protection, and system verification established to ensure system completeness.', 'Organization has a FAT procedure that requires vendors to demonstrate security of systems before they are purchased.', 'Governance and Risk Management', 'Governance and Risk Management', 0, NULL, 'AWWA', NULL, NULL, NULL, 88, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (30030, 'SI-2', 'System acceptance standards including data validation (input/output), message authenticity, and system integrity established to detect information corruption during processing.', 'Acquired assets are inspected, assessed, and documented before implementation with existing systems.', 'Governance and Risk Management', 'Governance and Risk Management', 0, NULL, 'AWWA', NULL, NULL, NULL, 88, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (30031, 'SI-4', 'Organization-wide clock synchronization system in place.', 'All managed network devices synchronize their clocks to a known good source.', 'Telecommunications, Network Security, and Architecture', 'Telecommunications, Network Security, and Architecture', 0, NULL, 'AWWA', NULL, NULL, NULL, 72, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (30032, 'CM-6', 'Risk based policies and procedures for change controls, reviews, and audits of SLAs.', 'Inviting all affected parties to discussions to prevent the development of vulnerabilities in the facility.', 'Governance and Risk Management', 'Governance and Risk Management', 0, NULL, 'AWWA', NULL, NULL, NULL, 88, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (30033, 'IA-2', 'Access control for the management, monitoring, review, and audit of accounts established including access control, account roles, privilege accounts, password policies and executive oversight.', 'Upon staff termination or resignation, login credentials are disabled as part of the Human Resources process.', 'Access Control', 'Access Control', 0, NULL, 'AWWA', NULL, NULL, NULL, 4, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (30034, 'IR-2', 'A security program established with a formal Emergency Response Plan to respond to security incidents monitor, discover, and handle security alerts and technical vulnerabilities, collect and analyze security data, limit the organization''s risk profile and', 'A SCADA tech believes a machine is infected and responds according to the utility''s emergency response plan for cybersecurity based incidents.', 'Governance and Risk Management', 'Governance and Risk Management', 0, NULL, 'AWWA', NULL, NULL, NULL, 88, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (30035, 'MA-1', 'A controlled maintenance system is in place to organize, schedule, document, and monitor the maintenance and repairs performed on information system assets in the PCS.', 'Based on the company''s controlled maintenance program, a utility will format network devices to factory settings before sending them out of the organization for maintenance.', 'Service Level Agreements (SLA)', 'Service Level Agreements (SLA)', 0, NULL, 'AWWA', NULL, NULL, NULL, 90, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (30036, 'MA-2', 'Maintenance of relationships with authorities, professional associations, interest groups etc., formalized.  This is done, in part, to maintain an up-to-date situational awareness of relevant threats.', 'The utility is a member of DHS''s CISA mailing list to receive frequent communications on PCS vulnerabilities discovered and patches available. SCADA techs regularly review alerts to determine if the alerts are applicable to their system.', 'Governance and Risk Management', 'Governance and Risk Management', 0, NULL, 'AWWA', NULL, NULL, NULL, 88, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (30037, 'MP-1', 'Storage media management and disposal program established to ensure that any sensitive data/software is used appropriately and is removed prior to media disposal (including approved policies and procedures).', 'When decommissioning a network device that was used in the production environment, IT is required to return it to factory conditions before it leaves the facility.', 'Governance and Risk Management', 'Governance and Risk Management', 0, NULL, 'AWWA', NULL, NULL, NULL, 88, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (30038, 'MP-3', 'Policies and procedure repository in place to be available to all authorized staff.', 'Company policies and procedures are available in a central, secure, shared location.', 'Governance and Risk Management', 'Governance and Risk Management', 0, NULL, 'AWWA', NULL, NULL, NULL, 88, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (30039, 'PM-5', 'Data classification policies and procedures for handling and labeling based on confidentiality and criticality approved and implemented.', 'A policy to store and manage access to PLC programs.', 'Governance and Risk Management', 'Governance and Risk Management', 0, NULL, 'AWWA', NULL, NULL, NULL, 88, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (30040, '5.2.1', 'A general product development/maintenance/support process shall be documented and enforced that is consistent and integrated with commonly accepted product development processes that include, but are not limited to:
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (30041, '5.3.1', 'A process shall be employed that identifies the organizational roles and personnel responsible for each of the processes required by this standard.', '<div>5.3.2 This process is required to ensure that responsibilities are assigned to elements of the product supplier''s organization for performing and completing the processes required by this standard.</div><div>Having this process means that the product supplier''s development, maintenance and product support processes required by this standard each identify the organizational roles and personnel that are responsible for performing and completing them. The organization and personnel can be within the developer’s organization or external to it.</div><div>NOTE A responsible, accountable,&nbsp;consulted and informed (RACI) matrix is an example of a tool that could be used to meet this requirement.</div>', 'Security Management', 'Securing the System', 0, NULL, 'ISA_62443_4_1', NULL, NULL, NULL, 45, NULL)
