INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id]) VALUES (1, 'AC.1.001', 'Limit information system access to authorized users, processes acting on behalf of authorized users, or devices (including other information systems).', '<ul><li>NIST SP 800-171 Rev 1 3.1.1</li><li>CIS Controls v7.1 1.4, 1.6, 5.1, 14.6, 15.10, 16.8, 16.9, 16.11</li><li>NIST CSF v1.1 PR.AC-1, PR.AC-3, PR.AC-4, PR.AC-6, PR.PT-3, PR.PT-4</li><li>CERT RMM v1.2 TM:SG4.SP1</li><li>NIST SP 800-53 Rev 4 AC-2, AC- 3, AC-17</li><li>AU ACSC Essential Eight</li></ul>', 'Access Control', 'Access Control', 1, 1, 2)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id]) VALUES (2, 'AC.1.002', 'Limit information system access to the types of transactions and functions that authorized users are permitted to execute.', '<ul><li>FAR Clause 52.204-21 b.1.ii</li><li>NIST SP 800-171 Rev 1 3.1.2</li><li>CIS Controls v7.1 1.4, 1.6, 5.1, 8.5, 14.6, 15.10, 16.8, 16.9, 16.11</li><li>NIST CSF v1.1 PR.AC-1, PR.AC-3, PR.AC-4, PR.AC-6, PR.PT-3, PR.PT-4</li><li>CERT RMM v1.2 TM:SG4.SP1</li><li>NIST SP 800-53 Rev 4 AC-2, AC- 3, AC-17</li></ul>', 'Access Control', 'Access Control', 1, 2, 2)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id]) VALUES (3, 'AC.1.003', 'Verify and control/limit connections to and use of external information systems.', '<ul><li>FAR Clause 52.204-21 b.1.iii</li><li>NIST SP 800-171 Rev 1 3.1.20</li><li>CIS Controls v7.1 12.1, 12.4</li><li>NIST CSF v1.1 ID.AM-4, PR.AC-3</li><li>CERT RMM v1.2 EXD:SG3.SP1</li><li>NIST SP 800-53 Rev 4 AC-20, AC- 20(1)</li></ul>', 'Access Control', 'Access Control', 1, 3, 2)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id]) VALUES (4, 'AC.1.004', 'Control information posted or processed on publicly accessible information systems.', '<ul><li>FAR Clause 52.204-21 b.1.iv</li><li>NIST SP 800-171 Rev 1 3.1.22</li><li>NIST SP 800-53 Rev 4 AC-22</li></ul>', 'Access Control', 'Access Control', 1, 4, 2)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id]) VALUES (5, 'AC.2.005', 'Provide privacy and security notices consistent with applicable CUI rules.', '<ul><li>NIST SP 800-171 Rev 1 3.1.9</li><li>NIST SP 800-53 Rev 4 AC-8</li></ul>', 'Access Control', 'Access Control', 2, 5, 2)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id]) VALUES (6, 'AC.2.006', 'Limit use of portable storage devices on external systems.', '<ul><li>NIST SP 800-171 Rev 1 3.1.21</li><li>CIS Controls v7.1 13.7, 13.8, 13.9</li><li>NIST CSF v1.1 ID.AM-4, PR.PT-2</li><li>NIST SP 800-53 Rev 4 AC-20(2)</li></ul>', 'Access Control', 'Access Control', 2, 6, 2)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id]) VALUES (7, 'AC.2.007', 'Employ the principle of least privilege, including for specific security functions and privileged accounts.', '<ul><li>NIST SP 800-171 Rev 1 3.1.5</li><li>CIS Controls v7.1 14.6</li><li>NIST CSF v1.1 PR.AC-4</li><li>CERT RMM v1.2 KIM:SG4.SP1</li><li>NIST SP 800-53 Rev 4 AC-6, AC- 6(1), AC-6(5)</li><li>UK NCSC Cyber Essentials</li></ul>', 'Access Control', 'Access Control', 2, 7, 2)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id]) VALUES (8, 'AC.2.008', 'Use non-privileged accounts or roles when accessing nonsecurity functions.', '<ul><li>NIST SP 800-171 Rev 1 3.1.6</li><li>CIS Controls v7.1 4.3, 4.6</li><li>NIST CSF v1.1 PR.AC-4</li><li>NIST SP 800-53 Rev 4 AC-6(2)</li><li>UK NCSC Cyber Essentials</li></ul>', 'Access Control', 'Access Control', 2, 8, 2)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id]) VALUES (9, 'AC.2.009', 'Limit unsuccessful logon attempts.', '<ul><li>NIST SP 800-171 Rev 1 3.1.8</li><li>NIST CSF v1.1 PR.AC-7</li><li>NIST SP 800-53 Rev 4 AC-7</li></ul>', 'Access Control', 'Access Control', 2, 9, 2)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id]) VALUES (10, 'AC.2.010', 'Use session lock with pattern-hiding displays to prevent access and viewing of data after a period of inactivity.', '<ul><li>NIST SP 800-171 Rev 1 3.1.10</li><li>CIS Controls v7.1 16.11</li><li>NIST SP 800-53 Rev 4 AC-11, AC- 11(1)</li></ul>', 'Access Control', 'Access Control', 2, 10, 2)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id]) VALUES (11, 'AC.2.011', 'Authorize wireless access prior to allowing such connections.', '<ul><li>NIST SP 800-171 Rev 1 3.1.16</li><li>CIS Controls v7.1 15.1, 15.10</li><li>NIST CSF v1.1 PR.PT-4</li><li>CERT RMM v1.2 TM:SG2.SP2</li><li>NIST SP 800-53 Rev 4 AC-18</li></ul>', 'Access Control', 'Access Control', 2, 11, 2)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id]) VALUES (12, 'AC.2.013', 'Monitor and control remote access sessions.', '<ul><li>NIST SP 800-171 Rev 1 3.1.12</li><li>CIS Controls v7.1 12.11, 12.12</li><li>NIST CSF v1.1 PR.AC-3, PR.PT-4</li><li>CERT RMM v1.2 TM:SG2.SP2</li><li>NIST SP 800-53 Rev 4 AC-17(1)</li></ul>', 'Access Control', 'Access Control', 2, 12, 2)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id]) VALUES (13, 'AC.2.015', 'Route remote access via managed access control points.', '<ul><li>NIST SP 800-171 Rev 1 3.1.14</li><li>CIS Controls v7.1 15.5, 15.10</li><li>NIST CSF v1.1 PR.AC-3, PR.PT-4</li><li>CERT RMM v1.2 TM:SG2.SP2</li><li>NIST SP 800-53 Rev 4 AC-17(3)</li></ul>', 'Access Control', 'Access Control', 2, 13, 2)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id]) VALUES (14, 'AC.2.016', 'Control the flow of CUI in accordance with approved authorizations.', '<ul><li>NIST SP 800-171 Rev 1 3.1.3</li><li>CIS Controls v7.1 12.1, 12.2, 12.5, 12.8, 13.3, 14.1, 14.6, 14.7</li><li>NIST CSF v1.1 ID.AM-3, PR.AC-5, PR.DS-5, PR.PT-4</li><li>CERT RMM v1.2 TM:SG4.SP1</li><li>NIST SP 800-53 Rev 4 AC-4</li><li>UK NCSC Cyber Essentials</li></ul>', 'Access Control', 'Access Control', 2, 14, 2)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id]) VALUES (15, 'AC.3.012', 'Protect wireless access using authentication and encryption.', '<ul><li>NIST SP 800-171 Rev 1 3.1.17</li><li>CIS Controls v7.1 15.7, 15.8</li><li>NIST CSF v1.1 PR.PT-4</li><li>CERT RMM v1.2 KIM:SG4.SP1</li><li>NIST SP 800-53 Rev 4 AC-18(1)</li></ul>', 'Access Control', 'Access Control', 3, 15, 2)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id]) VALUES (16, 'AC.3.014', 'Employ cryptographic mechanisms to protect the confidentiality of remote access sessions.', '<ul><li>NIST SP 800-171 Rev 1 3.1.13</li><li>CIS Controls v7.1 15.7, 15.8</li><li>NIST CSF v1.1 PR.AC-3, PR.PT-4</li><li>CERT RMM v1.2 KIM:SG4.SP1</li><li>NIST SP 800-53 Rev 4 AC-17(2)</li></ul>', 'Access Control', 'Access Control', 3, 16, 2)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id]) VALUES (17, 'AC.3.017', 'Separate the duties of individuals to reduce the risk of malevolent activity without collusion.', '<ul><li>NIST SP 800-171 Rev 1 3.1.4</li><li>NIST CSF v1.1 PR.AC-4</li><li>NIST SP 800-53 Rev 4 AC-5</li></ul>', 'Access Control', 'Access Control', 3, 17, 2)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id]) VALUES (18, 'AC.3.018', 'Prevent non-privileged users from executing privileged functions and capture the execution of such functions in audit logs.', '<ul><li>NIST SP 800-171 Rev 1 3.1.7</li><li>NIST CSF v1.1 PR.AC-4</li><li>CERT RMM v1.2 KIM:SG4.SP1</li><li>NIST SP 800-53 Rev 4 AC-6(9), AC-6(10)</li></ul>', 'Access Control', 'Access Control', 3, 18, 2)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id]) VALUES (19, 'AC.3.019', 'Terminate (automatically) user sessions after a defined condition.', '<ul><li>NIST SP 800-171 Rev 1 3.1.11</li><li>CIS Controls v7.1 16.7, 16.11</li><li>NIST SP 800-53 Rev 4 AC-12</li></ul>', 'Access Control', 'Access Control', 3, 19, 2)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id]) VALUES (20, 'AC.3.020', 'Control connection of mobile devices.', '<ul><li>NIST SP 800-171 Rev 1 3.1.18</li><li>CIS Controls v7.1 13.6, 16.7</li><li>NIST CSF v1.1 PR.AC-3, PR.AC-6</li><li>CERT RMM v1.2 TM:SG2.SP2</li><li>NIST SP 800-53 Rev 4 AC-19</li><li>UK NCSC Cyber Essentials</li></ul>', 'Access Control', 'Access Control', 3, 20, 2)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id]) VALUES (21, 'AC.3.021', 'Authorize remote execution of privileged commands and remote access to security relevant information.', '<ul><li>NIST SP 800-171 Rev 1 3.1.15</li><li>CIS Controls v7.1 8.8, 12.11, 12.12</li><li>NIST CSF v1.1 PR.AC-3, PR.PT-4</li><li>CERT RMM v1.2 TM:SG2.SP2</li><li>NIST SP 800-53 Rev 4 AC-17(4)</li></ul>', 'Access Control', 'Access Control', 3, 21, 2)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id]) VALUES (22, 'AC.3.022', 'Encrypt CUI on mobile devices and mobile computing platforms.', '<ul><li>NIST SP 800-171 Rev 1 3.1.19</li><li>CIS Controls v7.1 13.6</li><li>NIST CSF v1.1 PR.AC-3</li><li>CERT RMM v1.2 KIM:SG4.SP1</li><li>NIST SP 800-53 Rev 4 AC-19(5)</li></ul>', 'Access Control', 'Access Control', 3, 22, 2)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id]) VALUES (23, 'AC.4.023', 'Control information flows between security domains on connected systems.', '<ul><li>CMMC modification of Draft NIST SP 800-171B 3.1.3e</li><li>CIS Controls v7.1 12.1, 12.2, 13.1, 13.3, 14.1, 14.2, 14.5, 14.6, 14.7, 15.6, 15.10</li><li>NIST CSF v1.1 ID.AM-3, PR.AC-5, PR.DS-5, PR.PT-4, DE.AE-1</li><li>NIST SP 800-53 Rev 4 AC-4, AC- 4(1), AC-4(6), AC-4(8), AC-4(12), AC-4(13), AC-4(15), AC-4(20), <strike>SC-46</strike>&#160; (SC-46 removed per the CMMC Errata 20200318.pdf publication. See attached Source Documents.)</li></ul>', 'Access Control', 'Access Control', 4, 23, 2)
