INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id]) VALUES (27, 'AM.3.036', 'Define procedures for the handling of CUI data.', '<ul><li>CMMC</li></ul>', 'Asset Management', 'Management', 3, 27, 2)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id]) VALUES (28, 'AM.4.226', 'Employ a capability to discover and identify systems with specific component attributes (e.g., firmware level, OS type) within your inventory.', '<ul><li>CMMC modification of Draft NIST SP 800-171B 3.4.3e</li><li>CIS Controls v7.1 1.1, 1.2, 1.4, 1.5, 2.3, 2.4, 2.5</li><li>NIST CSF v1.1 ID.AM-1, ID.AM-2</li><li>CERT RMM v1.2 ADM:SG1.SP1</li><li>NIST SP 800-53 Rev 4 CM-8</li></ul>', 'Asset Management', 'Management', 4, 28, 2)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id]) VALUES (29, 'AT.2.056', 'Ensure that managers, system administrators, and users of organizational systems are made aware of the security risks associated with their activities and of the applicable policies, standards, and procedures related to the security of those systems.', '<ul><li>NIST SP 800-171 Rev 1 3.2.1</li><li>CIS Controls v7.1 17.3</li><li>NIST CSF v1.1 PR.AT-1, PR.AT-2, PR.AT-3, PR.AT-4, PR.AT-5</li><li>CERT RMM v1.2 OTA:SG1.SP1</li><li>NIST SP 800-53 Rev 4 AT-2, AT-3</li></ul>', 'Awareness and Training', 'Awareness and Training', 2, 29, 2)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id]) VALUES (30, 'AT.2.057', 'Ensure that personnel are trained to carry out their assigned information security related duties and responsibilities.', '<ul><li>NIST SP 800-171 Rev 1 3.2.2</li><li>CIS Controls v7.1 17.5, 17.6, 17.7, 17.8, 17.9</li><li>NIST CSF v1.1 PR.AT-1, PR.AT-2, PR.AT-3, PR.AT-4, PR.AT-5</li><li>CERT RMM v1.2 OTA:SG4.SP1</li><li>NIST SP 800-53 Rev 4 AT-2, AT-3</li></ul>', 'Awareness and Training', 'Awareness and Training', 2, 30, 2)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id]) VALUES (31, 'AT.3.058', 'Provide security awareness training on recognizing and reporting potential indicators of insider threat.', NULL, 'Awareness and Training', 'Awareness and Training', 3, 31, 2)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id]) VALUES (32, 'AT.4.059', 'Provide awareness training focused on recognizing and responding to threats from social engineering, advanced persistent threat actors, breaches, and suspicious behaviors; update the training at least annually or when there are significant changes to the threat.', '<ul><li>Draft NIST SP 800-171B 3.2.1e</li><li>CIS Controls v7.1 17.1, 17.2, 17.4</li><li>NIST CSF v1.1 PR.AT-1, PR.AT-2, PR.AT-3, PR.AT-4, PR.AT-5</li><li>CERT RMM v1.2 OTA:SG2.SP1 &#160;</li><li>NIST SP 800-53 Rev 4 AT-2, <strike>AT- 2(3), AT-2(4), AT-2(6), AT-2(7)</strike> (AT- 2(3), AT-2(4), AT-2(6), AT-2(7) were removed per the CMMC Errata 20200318.pdf publication, attached in source documents).&#160;</li></ul>', 'Awareness and Training', 'Awareness and Training', 4, 32, 2)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id]) VALUES (33, 'AT.4.060', 'Include practical exercises in awareness training that are aligned with current threat scenarios and provide feedback to individuals involved in the training.', '<ul><li>CMMC modification of Draft NIST SP 800-171B 3.2.2e</li><li>CIS Controls v7.1 17.1, 17.2, 17.4</li><li>NIST CSF v1.1 PR.AT-1, PR.AT-2, PR.AT-3, PR.AT-4, PR.AT-5</li><li>CERT RMM v1.2 OTA:SG3.SP1, OTA:SG3.SP2</li><li>NIST SP 800-53 Rev 4 AT-2(1), AT-2(8)</li></ul>', 'Awareness and Training', 'Awareness and Training', 4, 33, 2)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id]) VALUES (34, 'AU.2.041', 'Ensure that the actions of individual system users can be uniquely traced to those users so they can be held accountable for their actions.', '<ul><li>NIST SP 800-171 Rev 1 3.3.2</li><li>CIS Controls v7.1 16.8, 16.9</li><li>NIST CSF v1.1 DE.CM-1, DE.CM- 3, DE.CM-7</li><li>CERT RMM v1.2 MON:SG1.SP3</li><li>NIST SP 800-53 Rev 4 AU-2, AU- 3, AU-3(1), AU-6, AU-11, AU-12</li></ul>', 'Audit and Accountability', 'Audit and Accountability', 2, 34, 2)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id]) VALUES (35, 'AU.2.042', 'Create and retain system audit logs and records to the extent needed to enable the monitoring, analysis, investigation, and reporting of unlawful or unauthorized system activity.', '<ul><li>NIST SP 800-171 Rev 1 3.3.1</li><li>CIS Controls v7.1 6.2</li><li>NIST CSF v1.1. DE.CM-1, DE.CM- 3, DE.CM-7</li><li>CERT RMM v1.2 MON:SG2.SP3</li><li>NIST SP 800-53 Rev 4 AU-2, AU- 3, AU-3(1), AU-6, AU-11, AU-12</li></ul>', 'Audit and Accountability', 'Audit and Accountability', 2, 35, 2)
